old2='''    <section className="public-po-paper">\n'''
new2='''    <section className="public-po-pricing" style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 14, marginBottom: 18, overflow: "hidden" }}>\n      <div style={{ padding: "15px 18px", borderBottom: "1px solid #e5e7eb", display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center" }}>\n        <div><b style={{ display: "block", fontSize: 14 }}>Purchase Details & Pricing</b><small style={{ color: "#9ca3af" }}>Prices shown here are the transaction values saved with this evaluation link.</small></div>\n        <strong style={{ color: "#047857", fontSize: 16, whiteSpace: "nowrap" }}>{displayTotal > 0 ? `Php ${displayTotal.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "Price not recorded"}</strong>\n      </div>\n      <div style={{ overflowX: "auto" }}>\n        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>\n          <thead><tr style={{ background: "#f8fafc" }}>\n            {['Qty', 'Unit', 'Item / Description', 'Unit Price', 'Line Total'].map((head) => <th key={head} style={{ padding: "9px 12px", textAlign: head === "Item / Description" ? "left" : "right", color: "#64748b", fontSize: 10, textTransform: "uppercase", letterSpacing: ".5px", borderBottom: "1px solid #e5e7eb" }}>{head}</th>)}\n          </tr></thead>\n          <tbody>\n            {itemAmounts.filter((item) => item.description || item.qty || item.unitPrice || item.lineTotal).map((item, index) => <tr key={`${item.line}-${index}`}>\n              <td style={{ padding: "9px 12px", textAlign: "right", borderBottom: "1px solid #f1f5f9" }}>{item.qty || "—"}</td>\n              <td style={{ padding: "9px 12px", textAlign: "right", borderBottom: "1px solid #f1f5f9" }}>{item.unit || "—"}</td>\n              <td style={{ padding: "9px 12px", borderBottom: "1px solid #f1f5f9" }}>{item.description || "—"}</td>\n              <td style={{ padding: "9px 12px", textAlign: "right", borderBottom: "1px solid #f1f5f9", whiteSpace: "nowrap" }}>{item.unitPrice > 0 ? `Php ${item.unitPrice.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "—"}</td>\n              <td style={{ padding: "9px 12px", textAlign: "right", borderBottom: "1px solid #f1f5f9", whiteSpace: "nowrap", fontWeight: 700 }}>{item.lineTotal > 0 ? `Php ${item.lineTotal.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "—"}</td>\n            </tr>)}\n            {!itemAmounts.some((item) => item.description || item.qty || item.unitPrice || item.lineTotal) && <tr><td colSpan={5} style={{ padding: 18, textAlign: "center", color: "#94a3b8" }}>No item pricing has been recorded yet.</td></tr>}\n          </tbody>\n        </table>\n      </div>\n      <div style={{ display: "flex", justifyContent: "flex-end", padding: "12px 18px", background: "#f8fafc", borderTop: "1px solid #e5e7eb" }}>\n        <div style={{ minWidth: 230, display: "flex", justifyContent: "space-between", gap: 28, fontSize: 13 }}><span style={{ color: "#64748b" }}>Total Amount</span><b>{displayTotal > 0 ? `Php ${displayTotal.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "—"}</b></div>\n      </div>\n    </section>\n\n    <section className="public-po-paper">\n'''
if old2 not in s: raise SystemExit('public page pricing anchor not found')
