# ---------- firestore rules ----------
r=root/'firestore.rules'
s=r.read_text(encoding='utf-8')
old='''    match /evaluations/{evaluationId} {\n      allow read: if hasPermission('view_dashboard');\n      allow create: if hasPermission('create_evaluations') || hasPermission('import_excel')\n        || (\n          request.resource.data.publicToken is string\n          && request.resource.data.evaluatorRole in ['purchaser', 'requisitioner', 'amd_personnel']\n          && request.resource.data.poNumber == get(/databases/$(database)/documents/evaluationLinks/$(request.resource.data.publicToken)).data.po.poNumber\n          && get(/databases/$(database)/documents/evaluationLinks/$(request.resource.data.publicToken)).data.status == 'pending'\n        );\n      allow update: if hasPermission('edit_evaluations') || hasPermission('import_excel');\n'''
new='''    match /evaluations/{evaluationId} {\n      allow read: if hasPermission('view_dashboard');\n      // Public evaluation links are bearer links: the assigned evaluator does not need\n      // a Firebase/SISC account. The role, PO, and token must match the pending link.\n      allow create: if hasPermission('create_evaluations') || hasPermission('import_excel')\n        || (\n          request.resource.data.publicToken is string\n          && request.resource.data.evaluatorRole in ['purchaser', 'requisitioner', 'amd_personnel']\n          && request.resource.data.evaluatorRole == get(/databases/$(database)/documents/evaluationLinks/$(request.resource.data.publicToken)).data.evaluatorRole\n          && request.resource.data.poNumber == get(/databases/$(database)/documents/evaluationLinks/$(request.resource.data.publicToken)).data.po.poNumber\n          && get(/databases/$(database)/documents/evaluationLinks/$(request.resource.data.publicToken)).data.status == 'pending'\n        );\n      allow update: if hasPermission('edit_evaluations') || hasPermission('import_excel');\n'''
if old not in s: raise SystemExit('rules anchor not found')
s=s.replace(old,new)
r.write_text(s,encoding='utf-8')

# ---------- PurchaseOrderGenerator ----------
